Manacher 演算法可以計算以 $s[i]$（或者 $s[i]$ 和 $s[i+1]$）為迴文中心的最長迴文子串的長度。

此外，還可以：

- 判斷任意子串是否為迴文串。
- 計算從 $s[i]$ 開始的最長迴文子串的長度。
- 計算以 $s[i]$ 結尾的最長迴文子串的長度。

> **注**：Z 函式和 Manacher 演算法都會用到類似 Z-box 的概念，在學習時，可以對比體會。

Manacher 演算法模板：

```py [sol-Python3]
class Manacher:
    def __init__(self, s: str):
        # 將 s 改造為 t，這樣就不需要討論 len(s) 的奇偶性，因為新串 t 的每個迴文子串都是奇迴文串（都有迴文中心）
        # s 和 t 的下標轉換關係：
        # (si+1)*2 = ti
        # ti/2-1 = si
        # ti 為偶數，對應奇迴文串（從 2 開始）
        # ti 為奇數，對應偶迴文串（從 3 開始）
        t = "#".join("^" + s + "$")

        # 定義一個奇迴文串的迴文半徑=(長度+1)/2，即保留迴文中心，去掉一側後的剩餘字串的長度
        # half_len[i] 表示在 t 上的以 t[i] 為迴文中心的最長迴文子串的迴文半徑
        # 即 [i-half_len[i]+1, i+half_len[i]-1] 是 t 上的一個迴文子串
        half_len = [0] * (len(t) - 2)
        half_len[1] = 1

        # box_r 表示當前右邊界下標最大的迴文子串的右邊界下標+1
        # box_m 為該回文子串的中心位置
        # 二者的關係為 box_r = box_m + half_len[box_m]
        box_m = box_r = 0
        for i in range(2, len(half_len)):
            hl = 1
            if i < box_r:
                # 記 i 關於 box_m 的對稱位置 i'=box_m*2-i
                # 若以 i' 為中心的最長迴文子串範圍超出了以 box_m 為中心的迴文串的範圍
                # 則 half_len[i] 應先初始化為已知的迴文半徑 box_r-i，然後再繼續暴力匹配
                # 否則 half_len[i] 與 half_len[i'] 相等
                hl = min(box_r - i, half_len[box_m * 2 - i])

            # 暴力擴充套件
            # 演算法的複雜度取決於這部分執行的次數
            # 由於擴充套件之後 box_r 必然會更新（右移），且擴充套件的的次數就是 box_r 右移的次數
            # 因此演算法的複雜度 = O(len(t)) = O(n)
            while t[i - hl] == t[i + hl]:
                hl += 1
                box_m, box_r = i, i + hl

            half_len[i] = hl

        self.half_len = half_len

    # 判斷子串 s[l:r]（左閉右開）是否為迴文串
    def is_palindrome(self, l: int, r: int) -> bool:
        # 根據下標轉換關係得到子串 s[l:r] 在 t 中對應的迴文中心下標為 l+r+1
        # t 中迴文子串的長度為 hl*2-1
        # 由於其中 '#' 的數量總是比字母的數量多 1
        # 因此其在 s 中對應的迴文子串的長度為 hl-1
        return self.half_len[l + r + 1] > r - l  # half_len[l+r+1]-1 >= r-l

    # is_odd=True:  返回以 s[i] 為迴文中心的最長奇迴文子串長度
    # is_odd=False: 返回以 s[i] 和 s[i+1] 為迴文中心的最長偶迴文子串長度（若不存在，則為 0）
    def longest_palindrome_at(self, i: int, is_odd: bool) -> int:
        # 根據下標轉換關係得到在 t 中對應的迴文中心下標
        if is_odd:
            return self.half_len[i * 2 + 2] - 1
        return self.half_len[i * 2 + 3] - 1
```

```java [sol-Java]
class Manacher {
    private final int[] halfLen;

    public Manacher(String s) {
        // 將 s 改造為 t，這樣就不需要討論 s.length() 的奇偶性，因為新串 t 的每個迴文子串都是奇迴文串（都有迴文中心）
        // s 和 t 的下標轉換關係：
        // (si+1)*2 = ti
        // ti/2-1 = si
        // ti 為偶數，對應奇迴文串（從 2 開始）
        // ti 為奇數，對應偶迴文串（從 3 開始）
        int n = s.length();
        char[] t = new char[n * 2 + 3];
        Arrays.fill(t, '#');
        t[0] = '^';
        for (int i = 0; i < n; i++) {
            t[i * 2 + 2] = s.charAt(i);
        }
        t[n * 2 + 2] = '$';

        // 定義一個奇迴文串的迴文半徑=(長度+1)/2，即保留迴文中心，去掉一側後的剩餘字串的長度
        // halfLen[i] 表示在 t 上的以 t[i] 為迴文中心的最長迴文子串的迴文半徑
        // 即 [i-halfLen[i]+1, i+halfLen[i]-1] 是 t 上的一個迴文子串
        halfLen = new int[t.length - 2];
        halfLen[1] = 1;

        // boxR 表示當前右邊界下標最大的迴文子串的右邊界下標+1
        // boxM 為該回文子串的中心位置
        // 二者的關係為 boxR = boxM + halfLen[boxM]
        int boxM = 0;
        int boxR = 0;
        for (int i = 2; i < halfLen.length; i++) {
            int hl = 1;
            if (i < boxR) {
                // 記 i 關於 boxM 的對稱位置 i'=boxM*2-i
                // 若以 i' 為中心的最長迴文子串範圍超出了以 boxM 為中心的迴文串的範圍
                // 則 halfLen[i] 應先初始化為已知的迴文半徑 boxR-i，然後再繼續暴力匹配
                // 否則 halfLen[i] 與 halfLen[i'] 相等
                hl = Math.min(boxR - i, halfLen[boxM * 2 - i]);
            }

            // 暴力擴充套件
            // 演算法的複雜度取決於這部分執行的次數
            // 由於擴充套件之後 boxR 必然會更新（右移），且擴充套件的的次數就是 boxR 右移的次數
            // 因此演算法的複雜度 = O(t.length) = O(n)
            while (t[i - hl] == t[i + hl]) {
                hl++;
                boxM = i;
                boxR = i + hl;
            }

            halfLen[i] = hl;
        }
    }

	// 判斷 s 的子串 [l,r] 是否為迴文串
    public boolean isPalindrome(int l, int r) {
        // 根據下標轉換關係得到子串 s[l,r] 在 t 中對應的迴文中心下標為 l+r+2
        // t 中迴文子串的長度為 hl*2-1
        // 由於其中 '#' 的數量總是比字母的數量多 1
        // 因此其在 s 中對應的迴文子串的長度為 hl-1
		return halfLen[l + r + 2] > r - l + 1; // halfLen[l+r+2]-1 >= r-l+1
    }

    // isOdd=true:  返回以 s[i] 為迴文中心的最長奇迴文子串長度
    // isOdd=false: 返回以 s[i] 和 s[i+1] 為迴文中心的最長偶迴文子串長度（若不存在，則為 0）
    public int longestPalindromeAt(int i, boolean isOdd) {
        // 根據下標轉換關係得到在 t 中對應的迴文中心下標
        if (isOdd) {
            return halfLen[i * 2 + 2] - 1;
        }
        return halfLen[i * 2 + 3] - 1;
    }
}
```

