class Manacher {
    vector<int> half_len;

public:
    Manacher(const string& s) {
        // 將 s 改造為 t，這樣就不需要討論 s.size() 的奇偶性，因為新串 t 的每個迴文子串都是奇迴文串（都有迴文中心）
        // s 和 t 的下標轉換關係：
        // (si+1)*2 = ti
        // ti/2-1 = si
        // ti 為偶數，對應奇迴文串（從 2 開始）
        // ti 為奇數，對應偶迴文串（從 3 開始）
        string t = "^";
        for (char c : s) {
            t += '#';
            t += c;
        }
        t += "#$";

        // 定義一個奇迴文串的迴文半徑=(長度+1)/2，即保留迴文中心，去掉一側後的剩餘字串的長度
        // half_len[i] 表示在 t 上的以 t[i] 為迴文中心的最長迴文子串的迴文半徑
        // 即 [i-half_len[i]+1, i+half_len[i]-1] 是 t 上的一個迴文子串
        half_len.resize(t.size() - 2);
        half_len[1] = 1;

        // box_r 表示當前右邊界下標最大的迴文子串的右邊界下標+1
        // box_m 為該回文子串的中心位置
        // 二者的關係為 box_r = box_m + half_len[box_m]
        int box_m = 0, box_r = 0;
        for (int i = 2; i < half_len.size(); i++) {
            int hl = 1;
            if (i < box_r) {
                // 記 i 關於 box_m 的對稱位置 i'=box_m*2-i
                // 若以 i' 為中心的最長迴文子串範圍超出了以 box_m 為中心的迴文串的範圍
                // 則 half_len[i] 應先初始化為已知的迴文半徑 box_r-i，然後再繼續暴力匹配
                // 否則 half_len[i] 與 half_len[i'] 相等
                hl = min(box_r - i, half_len[box_m * 2 - i]);
            }

            // 暴力擴充套件
            // 演算法的複雜度取決於這部分執行的次數
            // 由於擴充套件之後 box_r 必然會更新（右移），且擴充套件的的次數就是 box_r 右移的次數
            // 因此演算法的複雜度 = O(t.size()) = O(n)
            while (t[i - hl] == t[i + hl]) {
                hl++;
                box_m = i;
                box_r = i + hl;
            }

            half_len[i] = hl;
        }
    }

    // 判斷 s 的子串 [l,r] 是否為迴文串
    bool is_palindrome(int l, int r) const {
        // 根據下標轉換關係得到子串 [l,r] 在 t 中對應的迴文中心下標為 l+r+2
        // t 中迴文子串的長度為 hl*2-1
        // 由於其中 '#' 的數量總是比字母的數量多 1
        // 因此其在 s 中對應的迴文子串的長度為 hl-1
        return half_len[l + r + 2] > r - l + 1; // half_len[l+r+2]-1 >= r-l+1
    }

    // is_odd=true:  返回以 s[i] 為迴文中心的最長奇迴文子串長度
    // is_odd=false: 返回以 s[i] 和 s[i+1] 為迴文中心的最長偶迴文子串長度（若不存在，則為 0）
    int longest_palindrome_at(int i, bool is_odd) const {
        // 根據下標轉換關係得到在 t 中對應的迴文中心下標
        if (is_odd) {
            return half_len[i * 2 + 2] - 1;
        }
        return half_len[i * 2 + 3] - 1;
    }
};
