	halfLen[1] = 1

	// boxR 表示當前右邊界下標最大的迴文子串的右邊界下標+1
	// boxM 為該回文子串的中心位置
	// 二者的關係為 boxR = boxM + halfLen[boxM]
	boxM, boxR := 0, 0
	for i := 2; i < len(halfLen); i++ {
		hl := 1
		if i < boxR {
			// 記 i 關於 boxM 的對稱位置 i'=boxM*2-i
			// 若以 i' 為中心的最長迴文子串範圍超出了以 boxM 為中心的迴文串的範圍
			// 則 halfLen[i] 應先初始化為已知的迴文半徑 boxR-i，然後再繼續暴力匹配
			// 否則 halfLen[i] 與 halfLen[i'] 相等
			hl = min(boxR-i, halfLen[boxM*2-i])
		}

		// 暴力擴充套件
		for t[i-hl] == t[i+hl] {
			hl++
			boxM, boxR = i, i+hl
		}

		halfLen[i] = hl
	}

	// 判斷子串 s[l:r]（左閉右開）是否為迴文串
	isPalindrome := func(l, r int) bool {
		// 根據下標轉換關係得到子串 s[l:r] 在 t 中對應的迴文中心下標為 l+r+1
        // t 中迴文子串的長度為 hl*2-1
        // 由於其中 '#' 的數量總是比字母的數量多 1
        // 因此其在 s 中對應的迴文子串的長度為 hl-1
		return halfLen[l+r+1] > r-l // halfLen[l+r+1]-1 >= r-l
	}

	// isOdd=true:  返回以 s[i] 為迴文中心的最長奇迴文子串長度
	// isOdd=false: 返回以 s[i] 和 s[i+1] 為迴文中心的最長偶迴文子串長度（若不存在，則為 0）
	midLen := func(i int, isOdd bool) int {
		// 根據下標轉換關係得到在 t 中對應的迴文中心下標
		if isOdd {
			return halfLen[i*2+2] - 1
		}
		return halfLen[i*2+3] - 1
	}


}
